-- Threads (slug — target libraries):
--   1. isaiah-34-the-indignation-of-yahuah-upon-all-nations-the-winepress-of-wrath
--        — NT (Revelation 14, 19) + Tanakh (Joel 3) [free]
--        (★★ the indignation upon all nations; the great winepress; the valley of decision)
--   2. isaiah-34-the-heavens-rolled-together-as-a-scroll-the-sixth-seal
--        — NT (Revelation 6, Matthew 24) + Tanakh (Joel 3) [free]
--        (★ the host of heaven dissolved; the sixth seal; the heaven rolled as a scroll)
--   3. isaiah-34-the-sword-of-yahuah-the-sacrifice-in-bozrah-the-day-of-vengeance
--        — NT (Revelation 19) + Tanakh (Isaiah 63, Obadiah 1) [free]
--        (★ the sword on Edom; the sacrifice in Bozrah; the year of recompences for the controversy of Zion)
--   4. isaiah-34-the-smoke-thereof-shall-go-up-for-ever
--        — NT (Revelation 14, 18, 19) [free]
--        (★ the burning pitch; the smoke that rises for ever and ever)
--   5. isaiah-34-a-habitation-of-dragons-the-unclean-birds-possess-it
--        — NT (Revelation 18) [free]
--        (★ the desolation possessed by unclean creatures; Babylon a cage of every unclean bird)
--   6. isaiah-34-seek-ye-out-of-the-book-of-yahuah-none-shall-fail
--        — NT (Matthew 24) + Tanakh (Isaiah 40) [free]
--        (★ the sure word; none of these shall fail; his mouth commanded, his spirit gathered)
--
-- Framing notes:
--   ★★ THE WINEPRESS OF WRATH (THREAD 1): *For the indignation of Yahuah (LORD) is upon all nations,
--      and his fury upon all their armies: he hath utterly destroyed them, he hath delivered them to
--      the slaughter* (34:2). The summoned nations are trodden in the great winepress: *the angel
--      thrust in his sickle into the earth, and gathered the vine of the earth, and cast it into the
--      great winepress of the wrath of Elohim (God). And the winepress was trodden without the city,
--      and blood came out of the winepress* (Revelation 14:19-20); *he treadeth the winepress of the
--      fierceness and wrath of El Shaddai (Almighty God)* (Revelation 19:15). Joel names the place:
--      *Multitudes, multitudes in the valley of decision* (Joel 3:14). Covenant-lawsuit: it is the
--      SYSTEM of nations exalting against Zion that is judged, never a people hated.
--   ★ THE SIXTH SEAL (THREAD 2): *And all the host of heaven shall be dissolved, and the heavens shall
--      be rolled together as a scroll... as the leaf falleth off from the vine, and as a falling fig
--      from the fig tree* (34:4). The sixth seal is the same undoing: *the stars of heaven fell unto
--      the earth, even as a fig tree casteth her untimely figs... and the heaven departed as a scroll
--      when it is rolled together* (Revelation 6:13-14); *the powers of the heavens shall be shaken*
--      (Matthew 24:29); *the stars shall withdraw their shining* (Joel 3:15). (A reverse thread
--      anchored in Rev 6 already laterals to Isaiah 34:4 — this is the Isaiah-34-SOURCED forward weave,
--      a distinct anchor and direction, not a duplicate.)
--   ★ THE SWORD ON EDOM / BOZRAH (THREAD 3): *For my sword shall be bathed in heaven: behold, it shall
--      come down upon Idumea... Yahuah (LORD) hath a sacrifice in Bozrah, and a great slaughter in the
--      land of Idumea* (34:5-6) — *for it is the day of the LORD'S vengeance, and the year of
--      recompences for the controversy of Zion* (34:8). Edom is the archetype of the nations; Obadiah:
--      *the day of Yahuah (LORD) is near upon all the heathen: as thou hast done, it shall be done unto
--      thee* (Obadiah 1:15). The ch63 winepress is the lateral mate — same Bozrah, same day/year pair:
--      *Who is this that cometh from Edom, with dyed garments from Bozrah... For the day of vengeance
--      is in mine heart, and the year of my redeemed is come* (Isaiah 63:1,4) — REFERENCED, the ch63
--      thread already built (isaiah-63-i-have-trodden-the-winepress-alone-the-word-of-elohim). The
--      sacrifice ends in the fowls' supper: *gather yourselves together unto the supper of the great
--      Elohim (God); That ye may eat the flesh of kings* (Revelation 19:17-18).
--   ★ THE SMOKE FOR EVER (THREAD 4): *the land thereof shall become burning pitch. It shall not be
--      quenched night nor day; the smoke thereof shall go up for ever* (34:9-10). The library's smoke-
--      that-rises-for-ever: *the smoke of their torment ascendeth up for ever and ever* (Rev 14:11);
--      *the smoke of her burning* (Rev 18:18); *her smoke rose up for ever and ever* (Rev 19:3).
--   ★ THE UNCLEAN CREATURES (THREAD 5): *it shall be an habitation of dragons, and a court for owls*
--      (34:13). Babylon's fall echoes it: *Babylon the great is fallen... is become the habitation of
--      devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird*
--      (Revelation 18:2). The judged system becomes a haunt of unclean things.
--   ★ THE SURE WORD (THREAD 6): *Seek ye out of the book of Yahuah (LORD), and read: no one of these
--      shall fail... for my mouth it hath commanded, and his spirit it hath gathered them* (34:16).
--      None of the word fails: *Heaven and earth shall pass away, but my words shall not pass away*
--      (Matthew 24:35); *the word of our Elohim (God) shall stand for ever* (Isaiah 40:8). The book of
--      Yahuah is the sure witness against which the day of recompence is read.
--   VERSES WITH NO SEPARATE ADD: v.3 (their slain cast out — the slaughter of T1, woven in prose),
--      v.7 (the unicorns/bullocks soaked with blood — the Bozrah sacrifice of T3), v.12 (the nobles
--      called but none there — the desolation of T5), v.17 (the lot cast, possess it for ever — the
--      sure word of T6, woven). All recorded, none silently skipped.

CREATE TEMP VIEW _s303_isa34_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1 (★★): the indignation upon all nations — the great winepress of wrath
    ('canon','isaiah',34,2,'canon','revelation',14,19,'free',
      E'*And the angel thrust in his sickle into the earth, and gathered the vine of the earth, and cast it into the great winepress of the wrath of Elohim (God)* (Revelation 14:19). The indignation Isaiah summons all nations to hear — *the indignation of Yahuah (LORD) is upon all nations, and his fury upon all their armies: he hath utterly destroyed them, he hath delivered them to the slaughter* (Isaiah 34:2) — is the gathering of the vine of the earth into *the great winepress of the wrath of Elohim (God)*. The nations delivered to slaughter are the clusters trodden in the press.'),
    ('canon','isaiah',34,2,'canon','revelation',14,20,'free',
      E'*And the winepress was trodden without the city, and blood came out of the winepress, even unto the horse bridles, by the space of a thousand and six hundred furlongs* (Revelation 14:20). The fury *upon all their armies* delivered *to the slaughter* (Isaiah 34:2) is the blood that comes out of the trodden winepress — the day of recompence rendered in full. The slaughter of the nations is the treading of the press.'),
    ('canon','isaiah',34,2,'canon','revelation',19,15,'free',
      E'*And out of his mouth goeth a sharp sword, that with it he should smite the nations: and he shall rule them with a rod of iron: and he treadeth the winepress of the fierceness and wrath of El Shaddai (Almighty God)* (Revelation 19:15). The *indignation of Yahuah (LORD)... upon all nations* (Isaiah 34:2) is wielded by the rider whose sword smites the nations and who *treadeth the winepress of the fierceness and wrath of El Shaddai (Almighty God)* — the Formed Son executing the Father''s recompence.'),
    ('canon','isaiah',34,2,'canon','joel',3,14,'free',
      E'*Multitudes, multitudes in the valley of decision: for the day of Yahuah (LORD) is near in the valley of decision* (Joel 3:14). The nations summoned to hear the *indignation of Yahuah (LORD)... upon all nations* (Isaiah 34:2) are the multitudes massed in Joel''s valley of decision — *the day of Yahuah (LORD) is near*. Joel names the gathering Isaiah pronounces: all nations brought down to judgment.'),
    ('canon','isaiah',34,1,'canon','joel',3,12,'free',
      E'*Let the heathen be wakened, and come up to the valley of Jehoshaphat: for there will I sit to judge all the heathen round about* (Joel 3:12). The summons *Come near, ye nations, to hear; and hearken, ye people* (Isaiah 34:1) is answered in Joel''s court — *there will I sit to judge all the heathen round about*. The nations are called near not to mercy but to the seat of judgment.'),

    -- THREAD 2 (★): the host of heaven dissolved — the sixth seal, the heaven rolled as a scroll
    ('canon','isaiah',34,4,'canon','revelation',6,14,'free',
      E'*And the heaven departed as a scroll when it is rolled together; and every mountain and island were moved out of their places* (Revelation 6:14). Isaiah''s undoing of the heavens — *the heavens shall be rolled together as a scroll* (Isaiah 34:4) — is the sixth seal word for word: *the heaven departed as a scroll when it is rolled together*. The day of vengeance shakes the very frame of the sky.'),
    ('canon','isaiah',34,4,'canon','revelation',6,13,'free',
      E'*And the stars of heaven fell unto the earth, even as a fig tree casteth her untimely figs, when she is shaken of a mighty wind* (Revelation 6:13). The host of heaven that falls *as the leaf falleth off from the vine, and as a falling fig from the fig tree* (Isaiah 34:4) is the sixth-seal star-fall — *even as a fig tree casteth her untimely figs*. The same fig-tree figure, the same heavens emptied.'),
    ('canon','isaiah',34,4,'canon','matthew',24,29,'free',
      E'*Immediately after the tribulation of those days shall the sun be darkened, and the moon shall not give her light, and the stars shall fall from heaven, and the powers of the heavens shall be shaken* (Matthew 24:29). When *the host of heaven shall be dissolved* (Isaiah 34:4), *the powers of the heavens shall be shaken* — Yahusha gathers Isaiah''s scroll-rolling and star-fall into the sign of the Son of Adam''s coming.'),
    ('canon','isaiah',34,4,'canon','joel',3,15,'free',
      E'*The sun and the moon shall be darkened, and the stars shall withdraw their shining* (Joel 3:15). The dissolving of *the host of heaven* (Isaiah 34:4) is Joel''s darkened luminaries — *the stars shall withdraw their shining*. The same day-of-Yahuah sky, the lights of heaven failing over the judgment of the nations.'),

    -- THREAD 3 (★): the sword on Edom — the sacrifice in Bozrah, the year of recompences for Zion
    ('canon','isaiah',34,6,'canon','revelation',19,17,'free',
      E'*And I saw an angel standing in the sun; and he cried with a loud voice, saying to all the fowls that fly in the midst of heaven, Come and gather yourselves together unto the supper of the great Elohim (God)* (Revelation 19:17). Yahuah''s *sacrifice in Bozrah, and a great slaughter in the land of Idumea* (Isaiah 34:6) is summoned to the table — *the supper of the great Elohim (God)*. The slaughter of the nations becomes the feast the fowls are gathered to.'),
    ('canon','isaiah',34,6,'canon','revelation',19,18,'free',
      E'*That ye may eat the flesh of kings, and the flesh of captains, and the flesh of mighty men, and the flesh of horses, and of them that sit on them, and the flesh of all men, both free and bond, both small and great* (Revelation 19:18). The sword *filled with blood... made fat with fatness... for Yahuah (LORD) hath a sacrifice in Bozrah* (Isaiah 34:6) is the very flesh the fowls eat — *the flesh of kings... and the flesh of all men*. The Bozrah sacrifice and the supper of the great Elohim are one slaughter of the exalted nations.'),
    ('canon','isaiah',34,5,'canon','isaiah',63,1,'free',
      E'*Who is this that cometh from Edom, with dyed garments from Bozrah? this that is glorious in his apparel, travelling in the greatness of his strength? I that speak in righteousness, mighty to save* (Isaiah 63:1). The sword that comes *down upon Idumea* (Isaiah 34:5) is the One who comes *from Edom, with dyed garments from Bozrah* — the same Bozrah, the same Edom, the day of vengeance executed in person (the ch63 winepress).'),
    ('canon','isaiah',34,8,'canon','isaiah',63,4,'free',
      E'*For the day of vengeance is in mine heart, and the year of my redeemed is come* (Isaiah 63:4). Isaiah names the day twice with the same paired words: *it is the day of the LORD''S vengeance, and the year of recompences for the controversy of Zion* (Isaiah 34:8) answers to *the day of vengeance is in mine heart, and the year of my redeemed is come* (63:4). The recompence on Edom and the redemption of Zion are the one day — the controversy of Zion vindicated.'),
    ('canon','isaiah',34,8,'canon','obadiah',1,15,'free',
      E'*For the day of Yahuah (LORD) is near upon all the heathen: as thou hast done, it shall be done unto thee: thy reward shall return upon thine own head* (Obadiah 1:15). The *year of recompences for the controversy of Zion* (Isaiah 34:8) is Obadiah''s measure-for-measure on Edom and all the heathen — *as thou hast done, it shall be done unto thee*. Edom is the archetype: the nation that gloated over Zion''s fall has its own deed returned upon its head.'),

    -- THREAD 4 (★): the smoke thereof shall go up for ever
    ('canon','isaiah',34,10,'canon','revelation',14,11,'free',
      E'*And the smoke of their torment ascendeth up for ever and ever: and they have no rest day nor night, who worship the beast and his image* (Revelation 14:11). The burning pitch that *shall not be quenched night nor day; the smoke thereof shall go up for ever* (Isaiah 34:10) is the smoke of the beast-worshippers'' torment — *the smoke of their torment ascendeth up for ever and ever... no rest day nor night*. The same unquenched fire, the same rising smoke without rest.'),
    ('canon','isaiah',34,10,'canon','revelation',18,18,'free',
      E'*And cried when they saw the smoke of her burning, saying, What city is like unto this great city!* (Revelation 18:18). The land become *burning pitch... the smoke thereof shall go up for ever* (Isaiah 34:10) is the smoke of fallen Babylon — *the smoke of her burning*. The judged system, whether Edom or Babylon, sends up the same testifying smoke.'),
    ('canon','isaiah',34,10,'canon','revelation',19,3,'free',
      E'*And again they said, Alleluia. And her smoke rose up for ever and ever* (Revelation 19:3). Isaiah''s *smoke thereof shall go up for ever* (Isaiah 34:10) is the heaven''s Alleluia over the great whore: *her smoke rose up for ever and ever*. The everlasting smoke of the judged system is the ground of heaven''s praise — for true and righteous are His judgments.'),

    -- THREAD 5 (★): a habitation of dragons — the unclean birds possess the desolation
    ('canon','isaiah',34,13,'canon','revelation',18,2,'free',
      E'*Babylon the great is fallen, is fallen, and is become the habitation of devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird* (Revelation 18:2). Idumea become *an habitation of dragons, and a court for owls* (Isaiah 34:13) is the very picture of fallen Babylon — *the habitation of devils... a cage of every unclean and hateful bird*. The judged system is left a haunt of unclean creatures, emptied of every noble inhabitant.'),

    -- THREAD 6 (★): seek ye out of the book of Yahuah — none of these shall fail (the sure word)
    ('canon','isaiah',34,16,'canon','matthew',24,35,'free',
      E'*Heaven and earth shall pass away, but my words shall not pass away* (Matthew 24:35). The charge *Seek ye out of the book of Yahuah (LORD), and read: no one of these shall fail* (Isaiah 34:16) is sealed by Yahusha''s own word: *my words shall not pass away*. Though the host of heaven is dissolved (34:4), the book of Yahuah does not fail — His mouth has commanded it.'),
    ('canon','isaiah',34,16,'canon','isaiah',40,8,'free',
      E'*The grass withereth, the flower fadeth: but the word of our Elohim (God) shall stand for ever* (Isaiah 40:8). *No one of these shall fail... for my mouth it hath commanded, and his spirit it hath gathered them* (Isaiah 34:16), because *the word of our Elohim (God) shall stand for ever* (40:8). The book of Yahuah is the sure witness against which the day of recompence is read; not one word of it falls.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s303_isa34_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s303_isa34_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-34-the-indignation-of-yahuah-upon-all-nations-the-winepress-of-wrath',
       E'The indignation of Yahuah upon all nations — the great winepress of wrath',
       E'Isaiah 34 opens with a summons of the whole earth to a courtroom: *Come near, ye nations, to hear; and hearken, ye people: let the earth hear, and all that is therein* (Isaiah 34:1). The verdict is the day of recompence on the nations: *For the indignation of Yahuah (LORD) is upon all nations, and his fury upon all their armies: he hath utterly destroyed them, he hath delivered them to the slaughter* (34:2). This is the great winepress the Revelation shows trodden: *the angel thrust in his sickle into the earth, and gathered the vine of the earth, and cast it into the great winepress of the wrath of Elohim (God). And the winepress was trodden without the city, and blood came out of the winepress* (Revelation 14:19-20) — *he treadeth the winepress of the fierceness and wrath of El Shaddai (Almighty God)* (Revelation 19:15), the Formed Son executing the Father''s sentence. Joel names the place the nations are gathered: *Let the heathen be wakened, and come up to the valley of Jehoshaphat: for there will I sit to judge all the heathen round about* (Joel 3:12); *Multitudes, multitudes in the valley of decision: for the day of Yahuah (LORD) is near in the valley of decision* (Joel 3:14). Read it as covenant-lawsuit, not ethnic hatred: it is the SYSTEM of nations that exalted itself against Zion that is delivered to the slaughter — the controversy of Zion is righteous, and the recompence is just.',
       sv.verse_id, ev.verse_id, 'free', 26825
  FROM _s303_isa34_lookup sv, _s303_isa34_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=1
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=34 AND ev.verse_number=2
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-34-the-heavens-rolled-together-as-a-scroll-the-sixth-seal',
       E'The heavens rolled together as a scroll — the sixth seal',
       E'The day of vengeance unmakes the very frame of the sky: *And all the host of heaven shall be dissolved, and the heavens shall be rolled together as a scroll: and all their host shall fall down, as the leaf falleth off from the vine, and as a falling fig from the fig tree* (Isaiah 34:4). The sixth seal is this word made vision: *the stars of heaven fell unto the earth, even as a fig tree casteth her untimely figs, when she is shaken of a mighty wind; And the heaven departed as a scroll when it is rolled together; and every mountain and island were moved out of their places* (Revelation 6:13-14) — the same scroll, the same fig-tree figure. Yahusha folds it into the sign of His coming: *the stars shall fall from heaven, and the powers of the heavens shall be shaken* (Matthew 24:29). And Joel sings the same darkened heavens over the judgment of the nations: *The sun and the moon shall be darkened, and the stars shall withdraw their shining* (Joel 3:15). When the nations are brought down, the host of heaven is dissolved with them — the cosmos itself testifies to the day of Yahuah.',
       sv.verse_id, ev.verse_id, 'free', 26828
  FROM _s303_isa34_lookup sv, _s303_isa34_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=4
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=34 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-34-the-sword-of-yahuah-the-sacrifice-in-bozrah-the-day-of-vengeance',
       E'The sword of Yahuah upon Edom — the sacrifice in Bozrah, the year of recompences for Zion',
       E'The sword comes down on Edom as the archetype of all the nations: *For my sword shall be bathed in heaven: behold, it shall come down upon Idumea, and upon the people of my curse, to judgment* (Isaiah 34:5). It is a sacrifice: *The sword of Yahuah (LORD) is filled with blood, it is made fat with fatness... for Yahuah (LORD) hath a sacrifice in Bozrah, and a great slaughter in the land of Idumea* (34:6) — *For it is the day of the LORD''S vengeance, and the year of recompences for the controversy of Zion* (34:8). Isaiah says the same day again with the same paired words in the Bozrah winepress: *Who is this that cometh from Edom, with dyed garments from Bozrah?... For the day of vengeance is in mine heart, and the year of my redeemed is come* (Isaiah 63:1,4) — the recompence on Edom and the redemption of Zion are one day. Obadiah measures it: *the day of Yahuah (LORD) is near upon all the heathen: as thou hast done, it shall be done unto thee: thy reward shall return upon thine own head* (Obadiah 1:15) — Edom, who gloated over Zion''s fall, has its own deed returned. And the sacrifice ends at the table: *gather yourselves together unto the supper of the great Elohim (God); That ye may eat the flesh of kings... and the flesh of all men* (Revelation 19:17-18). The Bozrah slaughter and the supper of the great Elohim are one feast on the exalted nations. Victims, not enemies: it is the proud SYSTEM under the curse that is judged, that Zion''s controversy may be vindicated.',
       sv.verse_id, ev.verse_id, 'free', 26831
  FROM _s303_isa34_lookup sv, _s303_isa34_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=5
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=34 AND ev.verse_number=8
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-34-the-smoke-thereof-shall-go-up-for-ever',
       E'The smoke thereof shall go up for ever — the land become burning pitch',
       E'The land of the judged nation is turned to unquenchable fire: *And the streams thereof shall be turned into pitch, and the dust thereof into brimstone, and the land thereof shall become burning pitch. It shall not be quenched night nor day; the smoke thereof shall go up for ever: from generation to generation it shall lie waste* (Isaiah 34:9-10). This is the smoke that rises for ever across the Revelation: *the smoke of their torment ascendeth up for ever and ever: and they have no rest day nor night, who worship the beast and his image* (Revelation 14:11); *they saw the smoke of her burning, saying, What city is like unto this great city!* (Revelation 18:18); and over the fallen whore, heaven''s Alleluia — *And her smoke rose up for ever and ever* (Revelation 19:3). The brimstone and the unquenched smoke are the signature of the judged system, the same pitch and fire that fell on Sodom; the recompence is everlasting and its testimony rises without rest.',
       sv.verse_id, ev.verse_id, 'free', 26834
  FROM _s303_isa34_lookup sv, _s303_isa34_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=9
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=34 AND ev.verse_number=10
ON CONFLICT (slug) DO NOTHING;

-- THREAD 5 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-34-a-habitation-of-dragons-the-unclean-birds-possess-it',
       E'A habitation of dragons — the unclean birds possess the desolation',
       E'When the nobles are gone and the kingdom is nothing — *They shall call the nobles thereof to the kingdom, but none shall be there, and all her princes shall be nothing* (Isaiah 34:12) — the desolation is given over to unclean creatures: *thorns shall come up in her palaces, nettles and brambles in the fortresses thereof: and it shall be an habitation of dragons, and a court for owls* (34:13); *the cormorant and the bittern shall possess it; the owl also and the raven shall dwell in it* (34:11); *the screech owl also shall rest there... There shall the great owl make her nest* (34:14-15). The Revelation paints fallen Babylon in the very same colors: *Babylon the great is fallen, is fallen, and is become the habitation of devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird* (Revelation 18:2). The judged system, emptied of every noble inhabitant, is left a haunt of unclean things — the line of confusion and the stones of emptiness (34:11) stretched over a kingdom returned to waste.',
       sv.verse_id, ev.verse_id, 'free', 26837
  FROM _s303_isa34_lookup sv, _s303_isa34_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=11
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=34 AND ev.verse_number=15
ON CONFLICT (slug) DO NOTHING;

-- THREAD 6 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-34-seek-ye-out-of-the-book-of-yahuah-none-shall-fail',
       E'Seek ye out of the book of Yahuah — no one of these shall fail',
       E'The chapter closes by sealing itself: *Seek ye out of the book of Yahuah (LORD), and read: no one of these shall fail, none shall want her mate: for my mouth it hath commanded, and his spirit it hath gathered them* (Isaiah 34:16). The desolation is not loose prophecy but written, commanded by His mouth and gathered by His Spirit — and not one word of it falls. Yahusha sets His own word on the same footing: *Heaven and earth shall pass away, but my words shall not pass away* (Matthew 24:35) — even when *the host of heaven shall be dissolved* (34:4), the book of Yahuah stands. Isaiah himself says it plainly: *The grass withereth, the flower fadeth: but the word of our Elohim (God) shall stand for ever* (Isaiah 40:8). The book of Yahuah is the sure witness against which the day of recompence is read and by which it is fulfilled; *he hath cast the lot for them, and his hand hath divided it unto them by line: they shall possess it for ever* (34:17) — His word performs what it has spoken.',
       sv.verse_id, ev.verse_id, 'free', 26840
  FROM _s303_isa34_lookup sv, _s303_isa34_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=16
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=34 AND ev.verse_number=17
ON CONFLICT (slug) DO NOTHING;

