  FROM cross_reference_threads t
  JOIN _s303_isa34_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=34 AND sv.verse_number=2
  JOIN _s303_isa34_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='revelation' AND tv.chapter_number=14 AND tv.verse_number=19
